package com.novalang.bukkit.types.world;
import com.novalang.bukkit.Requires; import com.novalang.bukkit.types.value.NovaTypeSupport; import com.novalang.runtime.host.JavaTypes; import org.bukkit.Location; import org.bukkit.World; import org.bukkit.block.DoubleChest; import org.bukkit.inventory.Inventory; import org.bukkit.inventory.InventoryHolder;
@Requires(classes = {"org.bukkit.block.DoubleChest"}) public final class NovaDoubleChest { private NovaDoubleChest() { } public static void register(JavaTypes.Builder b) { b.extension(DoubleChest.class,"inventory",f->f.returns(Inventory.class).invoke(a->NovaTypeSupport.argument(a,0,DoubleChest.class).getInventory())); b.extension(DoubleChest.class,"leftSide",f->f.returns(InventoryHolder.class).invoke(a->NovaTypeSupport.argument(a,0,DoubleChest.class).getLeftSide())); b.extension(DoubleChest.class,"rightSide",f->f.returns(InventoryHolder.class).invoke(a->NovaTypeSupport.argument(a,0,DoubleChest.class).getRightSide())); b.extension(DoubleChest.class,"location",f->f.returns(Location.class).invoke(a->NovaTypeSupport.argument(a,0,DoubleChest.class).getLocation())); b.extension(DoubleChest.class,"world",f->f.returns(World.class).invoke(a->NovaTypeSupport.argument(a,0,DoubleChest.class).getWorld())); }
}
